const interactionMap = {
	"": "",
	hover: "-hover",
	active: "-active",
	press: "-press",
	focus: "-focus",
	disabled: "-disabled",
	highlight: "-highlight",
};
const usageMap = {
	"": "",
	background: "-bg",
	bg: "-bg",
	text: "-text",
	border: "-border",
	"contrast-text": "-contrast-text",
	"vivid-text": "-vivid-text",
	"vivid-bg": "-vivid-bg",
};

type InteractionKey = keyof typeof interactionMap;
type UsageKey = keyof typeof usageMap;

type InteractionSelector = Partial<Record<InteractionKey, boolean>>;
type UsageSelector = Partial<Record<UsageKey, boolean>>;

export const color = (
	sentiment: string,
	usage?: UsageKey | UsageSelector,
	prominence?: string,
	interaction?: InteractionKey | InteractionSelector,
) => {
	const interactionKey =
		typeof interaction === "string" ? interaction : ("" as InteractionKey);
	const usageKey = typeof usage === "string" ? usage : ("" as UsageKey);

	let _interaction = interactionMap[interactionKey] ?? "";
	let _usage = usageMap[usageKey] ?? "";
	if (typeof interaction === "object") {
		for (const [key, value] of Object.entries(interaction)) {
			_interaction = interactionMap[(value ? key : "") as InteractionKey] ?? "";
		}
	}
	if (typeof usage === "object") {
		for (const [key, value] of Object.entries(usage)) {
			_usage = usageMap[(value ? key : "") as UsageKey] ?? "";
		}
	}

	const _prominence = prominence ? `-${prominence}` : "";

	if (_prominence === "dark") {
		return `var(--hbr-color-${sentiment}${_prominence})`;
	}
	return `var(--hbr-color-${sentiment}${_usage}${_prominence}${_interaction})`;
};
